import axios from 'axios';

// Base URL for API calls
const API_BASE_URL = 'http://localhost:8080';

// Configure axios defaults
axios.defaults.baseURL = API_BASE_URL;
axios.defaults.headers.common['Content-Type'] = 'application/json';

// Request interceptor to add auth token
axios.interceptors.request.use(
  (config) => {
    const token = localStorage.getItem('token');
    if (token) {
      config.headers.Authorization = `Bearer ${token}`;
    }
    return config;
  },
  (error) => {
    return Promise.reject(error);
  }
);

// Response interceptor to handle errors
axios.interceptors.response.use(
  (response) => response,
  (error) => {
    if (error.response?.status === 401) {
      // Token expired or invalid
      localStorage.removeItem('token');
      localStorage.removeItem('user');
      window.location.href = '/login';
    }
    return Promise.reject(error);
  }
);

// Auth API
export const authAPI = {
  login: (credentials) => axios.post('/api/auth/login', credentials),
  register: (userData) => axios.post('/api/auth/register', userData),
  getProfile: () => axios.get('/api/auth/profile'),
  testAuth: () => axios.get('/api/auth/test')
};

// Vendor API
export const vendorAPI = {
  // Profile management
  getProfile: () => axios.get('/api/vendor/profile'),
  createProfile: (profileData) => axios.post('/api/vendor/profile', profileData),
  updateProfile: (profileData) => axios.post('/api/vendor/profile', profileData),
  
  // Dashboard
  getDashboard: () => axios.get('/api/vendor/dashboard'),
  
  // Applications
  getApplications: () => axios.get('/api/vendor/applications'),
  createApplication: () => axios.post('/api/vendor/application'),
  submitApplication: (id) => axios.put(`/api/vendor/application/${id}/submit`)
};

// Admin API
export const adminAPI = {
  // Dashboard
  getDashboard: () => axios.get('/api/admin/dashboard'),
  
  // User management
  getPendingUsers: () => axios.get('/api/admin/pending-users'),
  verifyUser: (userId, approve) => axios.post(`/api/admin/verify-user/${userId}?approve=${approve}`),
  
  // Vendor management
  getAllVendors: () => axios.get('/api/admin/vendors'),
  getVendorsByRegion: (region) => axios.get(`/api/admin/vendors/region/${region}`),
  
  // Application management
  getAllApplications: () => axios.get('/api/admin/applications'),
  getApplicationsByStatus: (status) => axios.get(`/api/admin/applications/status/${status}`)
};

// Public API
export const publicAPI = {
  getAllVendors: () => axios.get('/getAllVendors'),
  addVendor: (vendorData) => axios.post('/addVendor', vendorData)
};

// Generic API helper
export const apiCall = async (apiFunction, ...args) => {
  try {
    const response = await apiFunction(...args);
    return { success: true, data: response.data };
  } catch (error) {
    console.error('API Error:', error);
    
    const errorMessage = error.response?.data?.error || 
                        error.response?.data?.message || 
                        error.message || 
                        'An error occurred';
    
    return { success: false, error: errorMessage };
  }
};

export default axios;
